-- Supabase Migration: Add qrcode column and partial unique index to ot_pos_gc_transaction
-- Date: 2026-11-24
-- Description:
--   Adds high-entropy digital voucher QR code field (`qrcode TEXT`) synced from
--   local MySQL `gc_sold.notes`, with a partial unique index to guarantee uniqueness
--   without conflicting on NULL/empty legacy records.
--   `uid` remains auto-generated by PostgreSQL (`DEFAULT uuid_generate_v4()`).

SET ROLE postgres;

ALTER TABLE public.ot_pos_gc_transaction
    ADD COLUMN IF NOT EXISTS qrcode TEXT;

CREATE UNIQUE INDEX IF NOT EXISTS uq_ot_pos_gc_trans_qrcode
    ON public.ot_pos_gc_transaction (qrcode)
    WHERE qrcode IS NOT NULL AND qrcode <> '';

NOTIFY pgrst, 'reload schema';
